/**
 * External dependencies
 */
import { isEqual, keyBy, omit } from 'lodash';
import type { AnyAction } from '@nab/types';

/**
 * Internal dependencies
 */
import { INIT_STATE } from './config';
import type { Action } from './actions';
import type { State } from './types';

export function reducer( state = INIT_STATE, action: AnyAction ): State {
	return actualReducer( state, action as Action ) ?? state;
}

function actualReducer( state: State, action: Action ): State {
	switch ( action.type ) {
		case 'ADD_CONVERSION_ACTION_TYPE_DEFINITIONS': {
			const newDefinitions = {
				...state.conversionActionTypeDefinitions,
				...keyBy( action.definitions, 'name' ),
			};
			if (
				isEqual( state.conversionActionTypeDefinitions, newDefinitions )
			) {
				return state;
			}

			return initializeConversionActionTypes( {
				...state,
				conversionActionTypeDefinitions: newDefinitions,
			} );
		}

		case 'REMOVE_CONVERSION_ACTION_TYPE_DEFINITIONS': {
			const newDefinitions = omit(
				state.conversionActionTypeDefinitions,
				action.names
			);
			if (
				isEqual( state.conversionActionTypeDefinitions, newDefinitions )
			) {
				return state;
			}

			return initializeConversionActionTypes( {
				...state,
				conversionActionTypeDefinitions: newDefinitions,
			} );
		}

		case 'ADD_CONVERSION_ACTION_TYPE_RUNTIMES': {
			const newRuntimes = action.runtimes.reduce(
				( runtimes, registration ) => ( {
					...runtimes,
					[ registration.name ]: registration.runtime,
				} ),
				state.conversionActionTypeRuntimes
			);
			if ( isEqual( state.conversionActionTypeRuntimes, newRuntimes ) ) {
				return state;
			}

			return initializeConversionActionTypes( {
				...state,
				conversionActionTypeRuntimes: newRuntimes,
			} );
		}

		case 'REMOVE_CONVERSION_ACTION_TYPE_RUNTIMES': {
			const newRuntimes = omit(
				state.conversionActionTypeRuntimes,
				action.names
			);
			if ( isEqual( state.conversionActionTypeRuntimes, newRuntimes ) ) {
				return state;
			}

			return initializeConversionActionTypes( {
				...state,
				conversionActionTypeRuntimes: newRuntimes,
			} );
		}
	}
}

function initializeConversionActionTypes( state: State ): State {
	const conversionActionTypes = Object.keys(
		state.conversionActionTypeDefinitions
	).reduce< State[ 'conversionActionTypes' ] >( ( types, name ) => {
		const runtime = state.conversionActionTypeRuntimes[ name ];
		if ( ! runtime ) {
			return types;
		}

		return {
			...types,
			[ name ]: {
				...state.conversionActionTypeDefinitions[ name ],
				...runtime,
			} as State[ 'conversionActionTypes' ][ string ],
		};
	}, {} );

	if ( isEqual( state.conversionActionTypes, conversionActionTypes ) ) {
		return state;
	}

	return {
		...state,
		conversionActionTypes,
	};
}
