/**
 * WordPress dependencies
 */
import { dispatch } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { isFunction } from 'lodash';
import { isValidIcon } from '@nab/utils';
import type {
	ConversionActionTypeDefinition,
	ConversionActionTypeName,
	ConversionActionTypeRuntime,
	Dict,
	Maybe,
} from '@nab/types';

/**
 * Internal dependencies
 */
import { store as NAB_ACTIONS } from '../store';

/**
 * Registers a conversion action definition provided a unique name and its
 * serializable metadata. Once registered, the definition is available to the
 * conversion-action store.
 *
 * @param {string} name       ConversionAction name.
 * @param {Object} definition ConversionAction definition.
 *
 * @return {?Object} The conversion action, if it has been successfully
 *                             registered; otherwise `undefined`.
 */
export function registerConversionActionTypeDefinition< T extends Dict = Dict >(
	name: ConversionActionTypeName,
	definition: Partial< ConversionActionTypeDefinition< T > >
): Maybe< ConversionActionTypeDefinition< T > > {
	if ( ! isValidName( name ) ) {
		return undefined;
	}

	if ( ! hasTitle( definition ) ) {
		// eslint-disable-next-line
		console.error(
			`Conversion action “${ name }” should specify a title.`
		);
		return undefined;
	}

	if ( ! hasCategory( definition ) ) {
		// eslint-disable-next-line
		console.error(
			`Conversion action “${ name }” should specify a category.`
		);
		return undefined;
	}

	if ( ! hasDescription( definition ) ) {
		// eslint-disable-next-line
		console.error(
			`Conversion action “${ name }” should specify a description.`
		);
		return undefined;
	}

	if ( ! hasDefaults( definition ) ) {
		// eslint-disable-next-line
		console.error(
			`Conversion action “${ name }” should specify its default attributes.`
		);
		return undefined;
	}

	const registeredDefinition = { name, ...definition };
	void dispatch( NAB_ACTIONS ).addConversionActionTypeDefinitions(
		registeredDefinition
	);
	return registeredDefinition as ConversionActionTypeDefinition< T >;
}

/**
 * Registers the browser runtime of a conversion action type.
 *
 * @param {string} name    ConversionAction name.
 * @param {Object} runtime ConversionAction runtime.
 * @return {?Object} The runtime, if it has been successfully registered;
 *                   otherwise `undefined`.
 */
export function registerConversionActionTypeRuntime< T extends Dict = Dict >(
	name: ConversionActionTypeName,
	runtime: Partial< ConversionActionTypeRuntime< T > >
): Maybe< ConversionActionTypeRuntime< T > > {
	if ( ! isValidName( name ) ) {
		return undefined;
	}

	if ( ! hasIcon( runtime ) ) {
		// eslint-disable-next-line
		console.error( `The conversion action “${ name }” must have an icon.` );
		return undefined;
	}

	if ( ! isValidIcon( runtime.icon ) ) {
		// eslint-disable-next-line
		console.error(
			'The icon passed is invalid. The icon should be an element or a function.'
		);
		return undefined;
	}

	if ( ! hasView( runtime ) ) {
		// eslint-disable-next-line
		console.error( 'The “view” property must be a valid function.' );
		return undefined;
	}

	if ( ! hasEdit( runtime ) ) {
		// eslint-disable-next-line
		console.error( 'The “edit” property must be a valid function.' );
		return undefined;
	}

	const registeredRuntime = runtime as ConversionActionTypeRuntime< T >;
	void dispatch( NAB_ACTIONS ).addConversionActionTypeRuntimes( {
		name,
		runtime: registeredRuntime as ConversionActionTypeRuntime,
	} );
	return registeredRuntime;
}

// =======
// HELPERS
// =======

const hasTitle = < T extends Dict = Dict >(
	x: Partial< ConversionActionTypeDefinition< T > >
): x is { title: ConversionActionTypeDefinition< T >[ 'title' ] } =>
	'string' === typeof x.title && !! x.title;

const hasCategory = < T extends Dict = Dict >(
	x: Partial< ConversionActionTypeDefinition< T > >
): x is { category: ConversionActionTypeDefinition< T >[ 'category' ] } =>
	'string' === typeof x.category && !! x.category;

const hasDescription = < T extends Dict = Dict >(
	x: Partial< ConversionActionTypeDefinition< T > >
): x is { description: ConversionActionTypeDefinition< T >[ 'description' ] } =>
	'string' === typeof x.description && !! x.description;

const hasDefaults = < T extends Dict >(
	x: Partial< ConversionActionTypeDefinition< T > >
): x is { defaults: ConversionActionTypeDefinition< T >[ 'defaults' ] } =>
	!! x.defaults;

const hasIcon = < T extends Dict = Dict >(
	x: Partial< ConversionActionTypeRuntime< T > >
): x is { icon: ConversionActionTypeRuntime< T >[ 'icon' ] } => 'icon' in x;

const hasView = < T extends Dict = Dict >(
	x: Partial< ConversionActionTypeRuntime< T > >
): x is { view: ConversionActionTypeRuntime< T >[ 'view' ] } =>
	isFunction( x.view );

const hasEdit = < T extends Dict = Dict >(
	x: Partial< ConversionActionTypeRuntime< T > >
): x is { edit: ConversionActionTypeRuntime< T >[ 'edit' ] } =>
	isFunction( x.edit );

function isValidName( name: ConversionActionTypeName ): boolean {
	if ( typeof name !== 'string' ) {
		// eslint-disable-next-line
		console.error( 'Conversion action names must be strings.' );
		return false;
	}

	if ( ! /^[a-z][a-z0-9-]*\/[a-z][a-z0-9-]*$/.test( name ) ) {
		// eslint-disable-next-line
		console.error(
			'Conversion action names must contain a namespace prefix, include only lowercase alphanumeric characters or dashes, and start with a letter. Example: my-plugin/my-custom-conversion-action'
		);
		return false;
	}

	return true;
}
