/**
 * External dependencies
 */
import { castArray } from 'lodash';
import type {
	ConversionActionTypeDefinition,
	ConversionActionTypeName,
	ConversionActionTypeRuntime,
} from '@nab/types';

export type Action =
	| AddConversionActionTypeDefinitions
	| RemoveConversionActionTypeDefinitions
	| AddConversionActionTypeRuntimes
	| RemoveConversionActionTypeRuntimes;

export function addConversionActionTypeDefinitions(
	definitions:
		| ConversionActionTypeDefinition
		| ReadonlyArray< ConversionActionTypeDefinition >
): AddConversionActionTypeDefinitions {
	return {
		type: 'ADD_CONVERSION_ACTION_TYPE_DEFINITIONS',
		definitions: castArray( definitions ),
	};
}

export function removeConversionActionTypeDefinitions(
	names: ConversionActionTypeName | ReadonlyArray< ConversionActionTypeName >
): RemoveConversionActionTypeDefinitions {
	return {
		type: 'REMOVE_CONVERSION_ACTION_TYPE_DEFINITIONS',
		names: castArray( names ),
	};
}

export function addConversionActionTypeRuntimes(
	runtimes:
		| ConversionActionTypeRuntimeRegistration
		| ReadonlyArray< ConversionActionTypeRuntimeRegistration >
): AddConversionActionTypeRuntimes {
	return {
		type: 'ADD_CONVERSION_ACTION_TYPE_RUNTIMES',
		runtimes: castArray( runtimes ),
	};
}

export function removeConversionActionTypeRuntimes(
	names: ConversionActionTypeName | ReadonlyArray< ConversionActionTypeName >
): RemoveConversionActionTypeRuntimes {
	return {
		type: 'REMOVE_CONVERSION_ACTION_TYPE_RUNTIMES',
		names: castArray( names ),
	};
}

// ============
// HELPER TYPES
// ============

type AddConversionActionTypeDefinitions = {
	readonly type: 'ADD_CONVERSION_ACTION_TYPE_DEFINITIONS';
	readonly definitions: ReadonlyArray< ConversionActionTypeDefinition >;
};

type RemoveConversionActionTypeDefinitions = {
	readonly type: 'REMOVE_CONVERSION_ACTION_TYPE_DEFINITIONS';
	readonly names: ReadonlyArray< ConversionActionTypeName >;
};

type AddConversionActionTypeRuntimes = {
	readonly type: 'ADD_CONVERSION_ACTION_TYPE_RUNTIMES';
	readonly runtimes: ReadonlyArray< ConversionActionTypeRuntimeRegistration >;
};

type RemoveConversionActionTypeRuntimes = {
	readonly type: 'REMOVE_CONVERSION_ACTION_TYPE_RUNTIMES';
	readonly names: ReadonlyArray< ConversionActionTypeName >;
};

export type ConversionActionTypeRuntimeRegistration = {
	readonly name: ConversionActionTypeName;
	readonly runtime: ConversionActionTypeRuntime;
};
