/**
 * WordPress dependencies
 */
import { createSelector } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { values } from 'lodash';
import type {
	ConversionActionType,
	ConversionActionTypeName,
	Dict,
	Maybe,
} from '@nab/types';

/**
 * Internal dependencies
 */
import type { State } from './types';

export const getConversionActionTypes = createSelector(
	( state: State ): ReadonlyArray< ConversionActionType > =>
		values( state.conversionActionTypes ),
	( state: State ) => [ state.conversionActionTypes ]
);

type GetConversionActionType = typeof _getConversionActionType & {
	CurriedSignature: < T extends Dict = Dict >(
		name: ConversionActionTypeName
	) => Maybe< ConversionActionType< T > >;
};
export const getConversionActionType =
	_getConversionActionType as GetConversionActionType;
function _getConversionActionType< T extends Dict = Dict >(
	state: State,
	name: ConversionActionTypeName
): Maybe< ConversionActionType< T > > {
	return state.conversionActionTypes[ name ] as ConversionActionType< T >;
}

export const getPageViewTriggerTypes = createSelector(
	( state: State ): ReadonlyArray< ConversionActionType > =>
		values( state.conversionActionTypes ).filter(
			( c ) => c.canBeUsedForPageViewTracking
		),
	( state: State ) => [ state.conversionActionTypes ]
);

export const getPageViewTriggerType = getConversionActionType;
